[3628] = "%s {{!sei|non sei}} talvolta immune a %s",
-- 893b04d1 English: %s {{!will|will not}} run
[3629] = "%s {{!verrà|non verrà}} eseguito",
-- 29755793 English: %s channeled spell {{!is|is not}} interruptible
[3630] = "l'incantesimo incanalato %s {{!è|non è}} interrompibile",
-- 372c957d English: %s spell {{!is|is not}} interruptible
[3631] = "l'incantesimo %s {{!è|non è}} interrompibile",
-- 970cadca English: You {{!know|do not know}} %s
[3632] = "{{!Conosci|Non conosci}} %s",
-- 6306f609 English: Your %s weapon {{!is|is not}} enchanted
[3633] = "La tua arma in %s {{!è|non è}} incantata",
-- 715d2919 English: Your pet {{!knows|does not know}} %s
[3634] = "Il tuo famiglio {{!conosce|non conosce}} %s",
-- a0f98b32 English: you {{!are|are not}} at least %s on %s
[3635] = "{{!sei|non sei}} almeno a %s su %s",
-- fa0b7d5f English: you {{!are|are not}} in %s
[3636] = "{{!sei|non sei}} in %s",
-- aaf9e864 English: your instance type {{!is|is not}} %s
[3637] = "il tuo tipo di istanza {{!è|non è}} %s",
-- 30f15e23 English: you {{!are|are not}} in a group
[3638] = "{{!sei|non sei}} in un gruppo",
-- f373fb95 English: you {{!are|are not}} outdoors
[3639] = "{{!sei|non sei}} all'aperto",
-- 09ee2b33 English: you {{!are|are not}} in a raid
[3640] = "{{!sei|non sei}} in un'incursione",
-- 4783037a English: you {{!are|are not}} in control of your character
[3641] = "{{!hai|non hai}} il controllo del tuo personaggio",
-- 39ec1678 English: you {{!are|are not}} moving
[3642] = "{{!ti stai|non ti stai}} muovendo",
-- 9993a0fe English: you {{!are|are not}} stealthed
[3643] = "{{!sei|non sei}} in furtività",
-- 3216151b English: you {{!are|are not}} talented in %s
[3644] = "{{!hai|non hai}} il talento %s",
-- 0d61ee4d English: you {{!have|do not have}} %s active
[3645] = "{{!hai|non hai}} %s attivo",
-- 568fa9d4 English: you {{!have|do not have}} a %s totem active where %s
[3646] = "{{!hai|non hai}} un totem di %s attivo in cui %s",
-- 06e77f0d English: you {{!have|do not have}} a pet
[3647] = "{{!hai|non hai}} un famiglio",
-- 8be0937e English: you {{!have|do not have}} a pet named {name}
[3648] = "{{!hai|non hai}} un famiglio di nome {name}",
-- 011430be English: your primary talent tree {{!is|is not}} %s
[3649] = "il tuo albero dei talenti principale {{!è|non è}} %s",
-- 1ebc1187 English: the zone's PVP status {{!is|is not}} %s
[3650] = "lo stato PvP della zona {{!è|non è}} %s",
-- 0bcca767 English: {{!in|not in}} {zone}
[3651] = "{{!in|non in}} {zone}",
-- c14661e2 English: Time in combat
[3652] = "Tempo in combattimento",
-- 33629208 English: %s {{!is|is not}} auto-repeating
[3653] = "%s {{!è|non è}} in ripetizione automatica",
-- 9544d41a English: Tests whether the selected spell is currently auto-repeating, such as Shoot or
--     Auto Shot. This is different from a spell being current or queued: a queued cast alone does
--     not satisfy this condition. Unavailable client observations remain unavailable even when
--     negated.
[3654] = "Verifica se l'incantesimo selezionato è attualmente in ripetizione automatica, come Tiro o Tiro Automatico. È diverso da un incantesimo attuale o in coda: un lancio in coda, da solo, non soddisfa questa condizione. Le osservazioni del client non disponibili restano non disponibili anche se negate.",
-- 32d5dd3a English: Uses readable positions in the same instance, or player-centered range
--     estimates when positions are unavailable. A unit counts only when its upper range bound is
--     within Distance. Uncertain positions, range, subgroup membership or required health/mana
--     values keep the whole condition unavailable, including under Unless. Percentage checks
--     require a positive maximum; empty aggregates have no result.
[3655] = "Usa le posizioni leggibili nella stessa istanza oppure, quando le posizioni non sono disponibili, stime della distanza centrate sul giocatore. Un'unità conta solo quando il limite superiore della sua distanza rientra in Distanza. Posizioni, distanze, appartenenza al sottogruppo o valori di salute/mana richiesti incerti rendono non disponibile l'intera condizione, anche con «Se non». I controlli percentuali richiedono un massimo positivo; gli aggregati vuoti non hanno risultato.",
-- 4953738e English: Count enemies when selected, or non-enemies when cleared.
[3656] = "Conta i nemici se selezionato, oppure i non nemici se deselezionato.",
-- 5179228a English: The number of observed units proven within Distance of you.
[3657] = "Il numero di unità osservate che risultano entro Distanza da te.",
-- 5f3da9f5 English: Counts the addon's observed unit snapshot, including nameplates and tracked
--     unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is
--     within Distance; uncertain membership or unreadable identity, hostility, range or nameplate
--     settings makes the whole count unavailable, including under Unless. Known vanished or reused
--     unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that
--     setting does not guarantee a complete scan.
[3658] = "Conta l'istantanea delle unità osservate dall'addon, comprese le targhette e gli alias di unità tracciati, non ogni unità vicina. Un'unità conta solo quando il limite superiore della sua distanza rientra in Distanza; un'appartenenza incerta, o identità, ostilità, distanza o impostazioni delle targhette illeggibili, rendono non disponibile l'intero conteggio, anche con «Se non». Gli identificativi unità noti come scomparsi o riutilizzati sono esclusi. Distanza non può superare l'impostazione attuale della distanza delle targhette; tale impostazione non garantisce una scansione completa.",
-- 60bfbfa2 English: you {{!have|do not have}} {item} equipped
[3659] = "{{!hai|non hai}} {item} equipaggiato",
-- 1d06a92b English: {item} {{!is|is not}} available{carrying}
[3660] = "{item} {{!è|non è}} disponibile{carrying}",
-- ac058958 English: {item} {{!is|is not}} in range{carrying}
[3661] = "{item} {{!è|non è}} a portata{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3662] = "il tempo di recupero di {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3663] = "{unit} {{!è|non è}} in un gruppo",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3664] = "{unit} {{!ti è amico|non ti è amico}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3665] = "Corrisponde quando l'unità selezionata è morta o un fantasma. Un'unità mancante o illeggibile non è disponibile, anche con NOT. In un annuncio Tramite macro, scegli Bersaglio dell'annuncio per seguire l'unità fornita.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3666] = "Corrisponde quando il gioco indica che l'unità selezionata ti è amica. Ciò non implica l'appartenenza al gruppo o all'incursione. Un'unità mancante o illeggibile non è disponibile.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3667] = "l'Assistente di Combattimento {{!sta|non sta}} suggerendo un incantesimo",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
[3668] = "l'Assistente di Combattimento {{!suggerisce|non suggerisce}} %s",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3669] = "Corrisponde quando l'Assistente di Combattimento di Blizzard suggerisce questo incantesimo come prossimo lancio. Una variante sostitutiva conta come il suo incantesimo base, e l'incantesimo base come la sua variante. Se non è scelto alcun incantesimo, corrisponde ogni volta che l'Assistente di Combattimento suggerisce qualcosa.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3670] = "L'Assistente di Combattimento esiste su Retail (ed è dichiarato su Forever). Dove il gioco non lo offre, per questo personaggio o questa specializzazione, o il suggerimento non può essere letto, questa condizione è non disponibile anziché falsa, anche sotto NOT.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
[3671] = "%s {{!è|non è}} nella rotazione dell'Assistente di Combattimento di Blizzard",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3672] = "Corrisponde quando questo incantesimo è uno di quelli che l'Assistente di Combattimento di Blizzard può suggerire per la tua specializzazione attuale. Contano anche la sua sostituzione attuale e il suo incantesimo base. Usala per evidenziare ciò che l'Assistente di Combattimento lascia fuori, per esempio un tempo di recupero che non fa parte dell'insieme.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3673] = "L'insieme viene riletto ogni volta che i tuoi incantesimi cambiano, mai indovinato. Dove il gioco non offre l'Assistente di Combattimento per questo personaggio o questa specializzazione, o l'insieme non si può leggere, questa condizione non è disponibile anziché falsa, anche con NOT.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3674] = "L'Assistente di Combattimento {{!è|non è}} disponibile",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3675] = "Corrisponde quando il gioco offre l'Assistente di Combattimento di Blizzard per il tuo personaggio e la tua specializzazione attuale. Quando non lo fa (per esempio una specializzazione per cui Blizzard non ha una rotazione dell'Assistente di Combattimento, o un client che dichiara l'API ma non offre la funzione), è falsa, così un ramo può ripiegare sui tuoi passi.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3676] = "Non disponibile solo dove il client non ha l'API dell'Assistente di Combattimento o la sua risposta non si può leggere, anche con NOT.",
-- 6f6ccc8f English: rune spell %s
[3677] = "incantesimo della runa %s",
