[3681] = "Le tue rune non sono ancora state caricate. Riapri tra poco questa condizione o inserisci un ID qui sotto.",
-- 1327b43b English: This character cannot engrave runes. A rune entered by ID below is kept, and is
--     unavailable here.
[3682] = "Questo personaggio non può incidere rune. Una runa inserita tramite ID qui sotto viene mantenuta e qui non è disponibile.",
