[3686] = "ID incantesimo della runa",
-- b84ca6e3 English: Rune ID
[3687] = "ID runa",
-- a698651e English: Matches when a Season of Discovery rune is engraved on one of your equipped
--     items. Passive runes count too, which a known-spell test cannot see.
[3688] = "Corrisponde quando una runa di Stagione della Scoperta è incisa su uno dei tuoi oggetti equipaggiati. Contano anche le rune passive, cosa che un test sugli incantesimi conosciuti non può vedere.",
-- 1daa202b English: Pick one of your known runes by equipment slot. The rune is saved by the first
--     spell it teaches, so a shared rotation names it on any character.
[3689] = "Scegli una delle tue rune conosciute tramite slot di equipaggiamento. La runa viene salvata tramite il primo incantesimo che insegna, quindi una rotazione condivisa la indica su qualsiasi personaggio.",
-- 8151a8cf English: Enter a spell the rune teaches, or the rune's own ID (its skill line ability
--     ID) for a rune that teaches no spell. Entering one clears the other.
[3690] = "Inserisci un incantesimo che la runa insegna, oppure l'ID proprio della runa (il suo ID abilità della linea di abilità) per una runa che non insegna alcun incantesimo. Inserirne uno cancella l'altro.",
-- 868afb4d English: Engraving exists only on Season of Discovery realms. Elsewhere, and until your
--     runes have loaded after logging in, this condition is unavailable rather than false,
--     including under NOT. The Phase 7 shoulder runes are not engravings and are not seen. This is
--     not the Death Knight Rune condition.
[3691] = "L'incisione esiste solo sui reami di Stagione della Scoperta. Altrove, e finché le tue rune non sono state caricate dopo l'accesso, questa condizione non è disponibile anziché falsa, anche con NOT. Le rune per le spalle della Fase 7 non sono incisioni e non vengono rilevate. Questa non è la condizione Runa del Cavaliere della Morte.",
-- 2cfaca8e English: Your talents cannot be listed right now (%s). A node ID entered below is kept
--     and evaluated.
[3692] = "I tuoi talenti non possono essere elencati al momento (%s). Un ID nodo inserito qui sotto viene conservato e valutato.",
-- 0d2b4c68 English: Talents can be listed only for your own class. A node ID entered below is kept
